import { useState, useEffect } from "react";
import {
  getToken,
  sendNotification,
  onMessageListener,
  initMessaging,
} from "dev-push-notification";

function App() {
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState("");

  const API_KEY = "YOUR_API_KEY";

  useEffect(() => {
    initMessaging(API_KEY);

    const unsubscribe = onMessageListener(async (payload) => {
      console.log("Foreground notification received:", payload);

      const { title, body, image } = payload.notification;

      const link = payload.data?.clickUrl || "/";

      const registration = await navigator.serviceWorker.ready;

      registration.showNotification(title, {
        body,
        icon: image,
        data: {
          clickUrl: link,
        },
      });
    });

    return () => unsubscribe();
  }, []);

  const handleGetToken = async () => {
    try {
      setLoading("getToken");

      const tokenData = await getToken(API_KEY);

      setToken(tokenData.token);

      console.log("Token Response:", tokenData);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading("");
    }
  };

  const handleSendNotification = async () => {
    try {
      setLoading("sendNotification");

      const response = await sendNotification({
        apiKey: API_KEY,
        title: "Hello User",
        body: "This is a test notification",
        icon: "https://your-domain.com/icon.png",
        link: "https://your-domain.com/dashboard",
        fcmTokens: [token],
      });

      console.log(response);
    } catch (error) {
      console.error(error);
    } finally {
      setLoading("");
    }
  };

  return (
    <div>
      <button onClick={handleGetToken}>
        {loading === "getToken"
          ? "Generating..."
          : "Generate Token"}
      </button>

      <button
        disabled={!token}
        onClick={handleSendNotification}
      >
        {loading === "sendNotification"
          ? "Sending..."
          : "Send Notification"}
      </button>
    </div>
  );
}

export default App;

